<?php require 'config.php';require_user();$id=(int)($_GET['id']??$_POST['destination_id']??0);$s=$pdo->prepare('SELECT * FROM destinations WHERE id=?');$s->execute([$id]);$d=$s->fetch();if(!$d)redirect('index.php');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$date=$_POST['travel_date']??'';$travelers=max(1,min(30,(int)($_POST['travelers']??1)));$message=trim($_POST['message']??'');if(!$date||$date<date('Y-m-d'))$error='Choose a valid future travel date.';else{$q=$pdo->prepare('INSERT INTO bookings(user_id,destination_id,travel_date,travelers,message) VALUES(?,?,?,?,?)');$q->execute([current_user()['id'],$id,$date,$travelers,$message]);flash('Trip request submitted. You can track its approval in My Trips.');redirect('my_bookings.php');}}
$page_title='Request a trip';require 'partials/header.php';?><section class="panel narrow"><span class="eyebrow">LET'S PLAN YOUR TRIP</span><h1><?=e($d['name'])?></h1><p class="muted">From ₹<?=number_format((float)$d['price'])?> per person. Admin approval is required before payment.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="destination_id" value="<?=$id?>"><div class="field"><label>Preferred travel date</label><input type="date" name="travel_date" min="<?=date('Y-m-d')?>" required></div><div class="field"><label>Number of travellers</label><input type="number" name="travelers" min="1" max="30" value="1" required></div><div class="field"><label>Special requests (optional)</label><textarea name="message" maxlength="1000" placeholder="Tell us any preferences..."></textarea></div><button class="btn btn-primary full">Submit trip request ↗</button></form></section><?php require 'partials/footer.php';?>
